function mainSlider() {
    const DEFAULT_MS = 7000;
    const root = document.querySelector('.main-slider');
    if (!root) return;

    // Задаёт длительность кольца и перезапускает анимацию активного буллета
    function setRingDuration(ms) {
        root.style.setProperty('--ring-duration', ms + 'ms');

        const ring = root.querySelector('.swiper-pagination-bullet-active .ring-progress');
        if (ring) {
            ring.style.setProperty('animation', 'none', 'important');
            void ring.offsetWidth;
            ring.style.removeProperty('animation');
        }
    }

    // Видео готово — убираем загрузку и плавно проявляем ролик
    function showVideo(video) {
        video.closest('.main__img')?.classList.add('_ready');
    }

    // Ловим момент, когда реально пошли кадры
    // (capture — сработает, даже если видео стартовало раньше скрипта)
    root.addEventListener('playing', e => {
        if (e.target.tagName === 'VIDEO') showVideo(e.target);
    }, true);
    root.addEventListener('timeupdate', e => {
        if (e.target.tagName === 'VIDEO' && e.target.currentTime > 0) showVideo(e.target);
    }, true);

    // Заморозить / отпустить кольцо пагинации
    function ringWait(on) {
        root.classList.toggle('_ring-wait', on);
    }

    // Обычный слайд — работает таймер Swiper
    function runAsImage(s) {
        ringWait(false);
        setRingDuration(DEFAULT_MS * 1.4);
        s.autoplay.start();
    }

    function handleSlide(s) {
        const slides = Array.from(s.slides);
        const video = slides[s.activeIndex]?.querySelector('video');

        // Остальные видео на паузу
        slides.forEach(sl => sl.querySelectorAll('video').forEach(v => {
            if (v !== video) v.pause();
        }));

        if (!video) {
            runAsImage(s);
            return;
        }

        // Видео-слайд: таймер выключаем
        s.autoplay.stop();

        // Слайд один — видео крутится бесконечно, иначе по окончании листаем дальше
        const single = s.slides.length === 1;
        video.loop = single;
        video.onended = single ? null : () => s.slideNext();

        // Кольцо стоит на нуле, пока видео реально не пошло
        ringWait(true);
        let ringStarted = false;
        video.onplaying = () => {
            if (!ringStarted) {
                ringStarted = true;
                const left = isFinite(video.duration) ? (video.duration - video.currentTime) * 1000 : DEFAULT_MS;
                setRingDuration(left * 1.4);
            }
            ringWait(false);
        };
        // Видео подвисло на подгрузке — кольцо тоже ждёт
        video.onwaiting = () => ringWait(true);

        // Видео уже играет (стартовало раньше скрипта)
        if (!video.paused && video.readyState >= 3) video.onplaying();

        const start = () => {
            const p = video.play();
            // Автозапуск запрещён (энергосбережение на iPhone и т.п.):
            // показываем первый кадр и листаем по обычному таймеру
            if (p && p.catch) p.catch(() => {
                if (video.readyState >= 2) showVideo(video);
                else video.addEventListener('loadeddata', () => showVideo(video), { once: true });
                runAsImage(s);
            });
        };

        if (video.readyState >= 1) start();
        else video.addEventListener('loadedmetadata', start, { once: true });
    }

    // Когда слайд уже скрыт — перематываем видео в начало
    function resetHidden(s) {
        Array.from(s.slides).forEach((sl, i) => {
            if (i === s.activeIndex) return;
            sl.querySelectorAll('video').forEach(v => {
                v.pause();
                if (v.currentTime > 0) v.currentTime = 0;
            });
        });
    }

    new Swiper('.main-slider .swiper-container', {
        slidesPerView: 1,
        spaceBetween: 20,
        rewind: true, // вместо loop: true — не клонирует слайд с видео
        autoplay: { delay: DEFAULT_MS, disableOnInteraction: false },
        speed: 800,
        effect: 'fade',
        fadeEffect: { crossFade: true },
        navigation: {
            nextEl: '.main-slider .swiper-button-next',
            prevEl: '.main-slider .swiper-button-prev',
        },
        pagination: {
            el: '.main-slider .swiper-pagination',
            clickable: true,
            renderBullet: (_, className) => `
                <span class="${className}">
                  <svg class="progress-ring" viewBox="0 0 26 26">
                    <circle class="ring-bg" cx="13" cy="13" r="10"></circle>
                    <circle class="ring-progress" cx="13" cy="13" r="10"></circle>
                  </svg>
                </span>
            `
        },
        on: {
            init: handleSlide,
            slideChange: handleSlide,
            slideChangeTransitionEnd: resetHidden,
        }
    });
}

mainSlider()

function Sliders() {
    let SlidersArray = []

    let sliders = document.querySelectorAll(".slider")
    sliders.forEach((slider,index) => {
        slider.setAttribute("data-slider-id",index)

        const isProducts = slider.classList.contains("products-slider")
        let autoplay = false
        let speed = 300

        let pagination = {
            el: `.slider[data-slider-id="${index}"] .swiper-pagination`,
            type: 'bullets',
            clickable: true,
        }

        if(slider.classList.contains("_autoplay")){
            autoplay = {
                delay: 3000,
                disableOnInteraction: false
            }
        }

        if(slider.classList.contains("advantages-slider")){
            speed = 800
        }

        if (isProducts) {
            autoplay = {
                delay: 2000,
                disableOnInteraction: true
            }
            speed = 900
        }

        function renderFraction(current,all) {
            slider.querySelector("._current").innerHTML = current
            slider.querySelector("._all").innerHTML = all
        }

        if(slider.classList.contains("article-slider")){
            pagination.type = 'fraction'
        }

        const swiper = new Swiper(`.slider[data-slider-id="${index}"] .swiper-container`, {
            slidesPerView: "auto",
            spaceBetween: 0,
            watchSlidesProgress: true,
            preventClicks :true,
            a11y: false,
            observer: true,
            observeParents: true,
            observeSlideChildren: true,
            autoplay,
            speed,
            navigation: {
                nextEl: `.slider[data-slider-id="${index}"] .swiper-button-next`,
                prevEl: `.slider[data-slider-id="${index}"] .swiper-button-prev`,
            },
            pagination: pagination,
            on: {
                init: function () {
                    if(slider.classList.contains("gallery-slider")){
                        renderFraction(
                            this.activeIndex+1,
                            this.slides.length
                        )
                    }
                },
                slideChange: function () {
                    if(slider.classList.contains("gallery-slider")){
                        renderFraction(
                            this.activeIndex+1,
                            this.slides.length
                        )
                    }
                },
            },
        })

        SlidersArray[index] = swiper

        if (isProducts) {
            initProductsAutoplay(slider, swiper)
        }
    })
}

function initProductsAutoplay(slider, swiper) {
    let userTookControl = false

    // Swiper сам запускает autoplay при инициализации — сразу останавливаем
    swiper.autoplay.stop()

    function takeControl() {
        if (userTookControl) return
        userTookControl = true
        swiper.autoplay.stop()
        observer.disconnect()
    }

    // свайп / драг мышью
    swiper.on("touchStart", takeControl)

    // стрелки и точки пагинации
    slider.querySelectorAll(".swiper-button-next, .swiper-button-prev, .swiper-pagination")
        .forEach(el => el.addEventListener("click", takeControl))

    // запуск при попадании блока в зону видимости
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (userTookControl) return

            if (entry.isIntersecting) {
                if (!swiper.autoplay.running) swiper.autoplay.start()
            } else {
                if (swiper.autoplay.running) swiper.autoplay.stop()
            }
        })
    }, {
        threshold: 0.5 // блок виден хотя бы наполовину
    })

    observer.observe(slider)
}

function gallery() {
    let SlidersArray = []

    let sliders = document.querySelectorAll(".gallery")
    sliders.forEach((slider,index) => {
        slider.setAttribute("data-slider-id",index)
        let gallery = {
            mySwiper: {},
            mySwiper2: {}
        }

        gallery.mySwiper = new Swiper(`.gallery[data-slider-id="${index}"] .mySwiper`, {
            spaceBetween: 0,
            slidesPerView: "auto",
            freeMode: true,
            watchSlidesProgress: true,
            direction: "vertical",
            breakpoints: {
                320: {
                    direction: "horizontal",
                },
                992: {
                    direction: "vertical",
                }
            }
        });
        gallery.mySwiper2 = new Swiper(`.gallery[data-slider-id="${index}"] .mySwiper2`, {
            spaceBetween: 0,
            direction: "vertical",
            loop: true,
            navigation: {
                nextEl: `.gallery[data-slider-id="${index}"] .swiper-button-next`,
                prevEl: `.gallery[data-slider-id="${index}"] .swiper-button-prev`,
            },
            thumbs: {
                swiper:  gallery.mySwiper,
            },
            breakpoints: {
                320: {
                    direction: "horizontal",
                },
                992: {
                    direction: "vertical",
                }
            }
        });

        SlidersArray[index] = gallery
    })

}


Sliders()
gallery()

const odometers = document.querySelectorAll("._number-animation");

const observer = new IntersectionObserver((entries, observer) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            const el = entry.target;
            const targetValue = parseInt(el.getAttribute("data-end"), 10);
            el.innerHTML = targetValue;
            observer.unobserve(el);
        }
    });
}, {
    threshold: 0.5
});

odometers.forEach(el => {
    let format = 'd'

    if(el.hasAttribute("data-thousands-separate")) {
        // format = '( ddd),dd'
    }
    new Odometer({
        el: el,
        value: 0,
        format,
        theme: 'default'
    });

    observer.observe(el);
});

let body = document.querySelector("body")
let modalTogglers = document.querySelectorAll("[data-modal]")
let modals = document.querySelectorAll(".modal")

modalTogglers.forEach(el => {
    el.onclick = function () {
        let modalId = el.getAttribute("data-modal")
        openModal(modalId)
    }
})

function closeModals() {
    modals.forEach(modal => {
        modal.classList.remove("_active")
        body.classList.remove("fixed-body2")
    })
}

function openModal(modalId) {
    closeModals()
    let modal = document.querySelector(`#${modalId}`)
    let closeButtons = modal.querySelectorAll(`._close-modal`)

    modal.classList.add("_active")
    body.classList.add("fixed-body2")


    closeButtons.forEach(btn => {
        btn.onclick = ()=> {
            modal.classList.remove("_active")
            body.classList.remove("fixed-body2")
        }
    })
}

var getScrollBarSize = (function() {
    var el = window.document.createElement('textarea'), style = {
        'visibility': 'hidden', 'position': 'absolute', 'zIndex': '-2147483647',
        'top': '-1000px', 'left': '-1000px', 'width': '1000px', 'height': '1000px',
        'overflow': 'scroll', 'margin': '0', 'border': '0', 'padding': '0'
    }, support = el.clientWidth !== undefined && el.offsetWidth !== undefined;

    for (var key in style) {
        if (style.hasOwnProperty(key)) {
            el.style[key] = style[key];
        }
    }

    return function() {
        var size = null;
        if (support && window.document.body) {
            window.document.body.appendChild(el);
            size = [el.offsetWidth - el.clientWidth, el.offsetHeight - el.clientHeight];
            window.document.body.removeChild(el);
        }

        document.documentElement.style.setProperty('--scrollWidth', `${size[0]}px`);
        return size;
    };
})();


window.addEventListener('DOMContentLoaded', () => {
    fix100vh();
    window.addEventListener('resize', () => {
        fix100vh();
        getScrollBarSize()
    })

    getScrollBarSize()

    $('input[type="tel"]').mask('+7 (999) 999-99-99', { autoclear: false }, { placeholder: '+7 (   )    -  -  ' });
})

function fix100vh() {
    let vh = window.innerHeight * 0.01;
    document.documentElement.style.setProperty('--vh', `${vh}px`);
}

function equalizeTabsHeight() {
    document.querySelectorAll('.main-sell').forEach(section => {
        const tabs = section.querySelectorAll('.tab-content');
        let maxHeight = 0;

        tabs.forEach(tab => {
            // сбрасываем прошлое значение, чтобы мерить реальную высоту
            tab.style.minHeight = '';

            // временно показываем скрытую вкладку для замера
            const prevDisplay = tab.style.display;
            tab.style.display = 'block';

            maxHeight = Math.max(maxHeight, tab.offsetHeight);

            tab.style.display = prevDisplay;
        });

        tabs.forEach(tab => {
            tab.style.minHeight = maxHeight + 'px';
        });
    });
}

window.addEventListener('load', equalizeTabsHeight);

let resizeTimer;
window.addEventListener('resize', () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(equalizeTabsHeight, 150);
});

